+
+	if (drm_WARN_ON(&pfdev->base, !perfcnt))
+		return;
+
+	lockdep_assert_held(&pfdev->reset.lock);
+
+	if (!perfcnt->user)
+		return;
+
+	ret = panfrost_perfcnt_hw_enable(pfdev);
+	if (ret)
+		perfcnt->reset_failed = true;
+}
